SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, COUNT(DISTINCT quantity) AS unique_products FROM inventory WHERE quantity BETWEEN 139 AND 145 OR store_id IN (2, 3) GROUP BY last_restock_cohort ORDER BY last_restock_cohort;
